# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MUSTAFA 1881-1920 TARİHE ATILAN İMZA: MİLLÎ MÜCADELE VE İKNA</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Tema ve Değerler (1881-1920)</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• <tspan font-weight="bold">Selanik (1881):</tspan> Çocukluk ve eğitim</text>\n  <text x="40" y="120" font-size="11" fill="#334155">• <tspan font-weight="bold">Çanakkale (1915):</tspan> Askeri deha</text>\n  <text x="40" y="142" font-size="11" fill="#334155">• <tspan font-weight="bold">Samsun (1919):</tspan> Millî Mücadele</text>\n  <text x="40" y="164" font-size="11" fill="#334155">• <tspan font-weight="bold">TBMM (1920):</tspan> Millî Egemenlik</text>\n  <text x="130" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Vatanseverlik ve İleri Görüşlülük</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Düşünceyi Geliştirme Yolları</text>\n  <text x="260" y="98" font-size="11" fill="#334155">• <tspan font-weight="bold">Tanımlama:</tspan> &quot;...nedir?&quot; cevabı</text>\n  <text x="260" y="120" font-size="11" fill="#334155">• <tspan font-weight="bold">Karşılaştırma:</tspan> En, daha, ise</text>\n  <text x="260" y="142" font-size="11" fill="#334155">• <tspan font-weight="bold">Örneklendirme:</tspan> Somut kanıtlar</text>\n  <text x="260" y="164" font-size="11" fill="#334155">• <tspan font-weight="bold">Tanık Gösterme:</tspan> Söz alıntısı</text>\n  <text x="260" y="186" font-size="11" fill="#334155">• <tspan font-weight="bold">Sayısal Veriler:</tspan> Tarih / istatistik</text>\n  <text x="350" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Metinde İkna Etme Teknikleri</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">Söz Sanatları (Edebî Sanatlar)</text>\n  <text x="480" y="98" font-size="11" fill="#334155">• <tspan font-weight="bold">Benzetme:</tspan> Zayıfı güçlüye</text>\n  <text x="488" y="114" font-size="10.5" fill="#475569">benzetme (gibi, kadar, misali)</text>\n  <text x="480" y="138" font-size="11" fill="#334155">• <tspan font-weight="bold">Kişileştirme:</tspan> İnsana ait özelliği</text>\n  <text x="488" y="154" font-size="10.5" fill="#475569">doğaya verme (ağlayan bulut)</text>\n  <text x="480" y="178" font-size="11" fill="#334155">• <tspan font-weight="bold">Abartma (Mübalağa):</tspan> Aşırı</text>\n  <text x="488" y="194" font-size="10.5" fill="#475569">büyütme veya küçültme</text>\n  <text x="570" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">• Konuşturma (İntak) &amp; Tezat (Zıtlık)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">FİİLLERDE KİP EKLERİ: HABER (BİLDİRME) VE DİLEK (TASARLAMA) KİPLERİ</text>\n  <rect x="30" y="50" width="310" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Haber (Bildirme) Kipleri (Zaman Anlamlı)</text>\n  <text x="48" y="102" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#1e40af">Bilinen (Görülen) Geçmiş Zaman (-dı/-di):</tspan> yaz-dı</text>\n  <text x="48" y="128" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#1e40af">Duyulan (Öğrenilen) Geçmiş (-mış/-miş):</tspan> yaz-mış</text>\n  <text x="48" y="154" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#1e40af">Şimdiki Zaman (-yor / -makta):</tspan> yaz-ıyor</text>\n  <text x="48" y="180" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#1e40af">Gelecek Zaman (-acak/-ecek):</tspan> yaz-acak</text>\n  <text x="48" y="206" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#1e40af">Geniş Zaman (-r/-ar/-er / -maz):</tspan> yaz-ar</text>\n  <rect x="360" y="50" width="310" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="515" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">2. Dilek (Tasarlama) Kipleri (Zaman Yok)</text>\n  <text x="378" y="102" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#991b1b">Gereklilik Kipi (-malı/-meli):</tspan> çalış-malı-yız</text>\n  <text x="378" y="130" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#991b1b">Dilek-Şart Kipi (-sa/-se):</tspan> çalış-sa-k</text>\n  <text x="378" y="158" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#991b1b">İstek Kipi (-a/-e):</tspan> çalış-a-lım / çalış-a-sın</text>\n  <text x="378" y="186" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#991b1b">Emir Kipi (Kip eki yoktur):</tspan> çalış / çalış-ın</text>\n  <text x="515" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">(1. tekil \'ben\' ve 1. çoğul \'biz\' emir çekimi yoktur!)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ÇEKİMLİ FİİL FORMÜLÜ VE KİŞİ (ŞAHIS) EKLERİ</text>\n  <rect x="30" y="50" width="640" height="62" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Çekimli Fiil = Fiil Kök veya Gövdesi + Kip Eki + Kişi (Şahıs) Eki</text>\n  <text x="350" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Örnek: &quot;başar-acak-sınız&quot; → başar- (Fiil Kökü) + -acak (Gelecek Zaman Kipi) + -sınız (2. Çoğul Kişi)</text>\n  <rect x="30" y="124" width="310" height="112" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="148" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Tekil Kişi Çekimleri</text>\n  <text x="48" y="172" font-size="11.5" fill="#334155">• <tspan font-weight="bold">1. Tekil (Ben):</tspan> okuyor-um / okudu-m</text>\n  <text x="48" y="194" font-size="11.5" fill="#334155">• <tspan font-weight="bold">2. Tekil (Sen):</tspan> okuyor-sun / okudu-n</text>\n  <text x="48" y="216" font-size="11.5" fill="#334155">• <tspan font-weight="bold">3. Tekil (O):</tspan> okuyor (Kişi eki yoktur / -sın)</text>\n  <rect x="360" y="124" width="310" height="112" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="515" y="148" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">Çoğul Kişi Çekimleri</text>\n  <text x="378" y="172" font-size="11.5" fill="#334155">• <tspan font-weight="bold">1. Çoğul (Biz):</tspan> okuyor-uz / okudu-k / okuya-lım</text>\n  <text x="378" y="194" font-size="11.5" fill="#334155">• <tspan font-weight="bold">2. Çoğul (Siz):</tspan> okuyor-sunuz / okudu-nuz</text>\n  <text x="378" y="216" font-size="11.5" fill="#334155">• <tspan font-weight="bold">3. Çoğul (Onlar):</tspan> okuyor-lar / okudu-lar</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
